    "content": "银喉 观鸟就是一种追逐与失落不断重复的过程。 若干年以前，在园子里散步的时候，耳边经常能听到竹丛中有一种微弱的、细碎的、若有若无的“叽叽”声，若是注意看，还可以看到竹叶有轻微的晃动，你判断这是一种鸟类的动静，但是你经常看不到鸟的身影。偶然的一次，你听到叽叽声后不久在竹子上看到了一只小鸟，大概灰白色或者灰黄色，个头儿非常的小，比麻雀小很多，但是尾巴似乎很长，小鸟很快就消失了，之后你经常在园子里找，却再也没有见过了。今年热衷于观鸟以来，经常扛着相机在小区里转悠，有一天在小池塘栈桥上，突然又听到了那种似曾相识的叽叽声，你…"
