    "author": "曹奕博,刘艺淳,牛梦彤",
    "description": "新华社日本名古屋10月2日电 题：记者手记：虚拟世界格斗梦，在亚运会上成真了 新华社记者曹奕博、牛梦彤、刘艺淳 还记得小时候看过的那些科幻电影吗？戴上虚拟现实（VR）头盔或接入其他装置，就能进入虚拟世界，和其他玩家近身格斗……随着虚拟跆拳道2日在爱知·名古屋亚运会完成“首秀”，“科幻”正成为现实。 虚拟跆拳道算得上最“年轻”的亚运项目——距离名古屋亚运会开幕还剩三个多月时，才正式拿到“入场券”。那么，这个新项目为什么能“压哨”入围？ 虽…",
    "content": "新华社日本名古屋10月2日电 题：记者手记：虚拟世界格斗梦，在亚运会上成真了 新华社记者曹奕博、牛梦彤、刘艺淳 还记得小时候看过的那些科幻电影吗？戴上虚拟现实（VR）头盔或接入其他装置，就能进入虚拟世界，和其他玩家近身格斗……随着虚拟跆拳道2日在爱知·名古屋亚运会完成“首秀”，“科幻”正成为现实。 虚拟跆拳道算得上最“年轻”的亚运项目——距离名古屋亚运会开幕还剩三个多月时，才正式拿到“入场券”。那么，这个新项目为什么能“压哨”入围？ 虽无身体接触，却不乏“腿腿到肉”的格斗激情——这是记者在虚拟跆拳道比赛现场最真实的…"
