    "content": "新华社平壤10月2日电（记者王天僚）据朝中社2日报道，朝鲜劳动党中央委员会部长金与正当天发表谈话，就日前发生在朝韩非军事区的地雷爆炸事件，谴责韩方企图把朝鲜半岛局势再次拖入危险境地。 金与正在谈话中说，地雷爆炸事件是韩方“自编自演的新闹剧”，韩方所谓事件是由朝方引起的结论“荒唐”。 金与正表示，朝鲜正在进行的南部边境要塞化工程，其目的在于“永远关闭边境来避免同韩国的任何接触”，朝方“不允许留下任何与韩国纠缠或打交道的余地”。她同时要求韩方“立即停止企图抹黑朝鲜形象的胡说八道”。 据韩联社电视台9月21日援引韩国军方…"
