    "content": "新华社伦敦10月2日电（记者张枫）根据颇具争议的《2026年量刑法案》，英国英格兰和威尔士地区于1日正式实施提前释放囚犯政策。据英国媒体报道，约700名囚犯当天出狱。 报道称，尽管提前获释的囚犯将佩戴电子监控脚环，但这一政策仍引发担忧。英格兰和威尔士缓刑事务首席监察员马丁·琼斯说，电子监控体系会造成“虚假的安全感”。 另据英国媒体估计，到2027年6月，将有约4500名囚犯因该政策提前出狱。 英国监狱系统长期处于高负荷运转状态。以囚禁英国九成犯人的英格兰和威尔士地区为例，其监狱总容量约为8.9万人。英国司法部数据显…"
