    "content": "10月2日，国庆假期第二天，旅游市场持续火爆。 澎湃新闻（www.thepaper.cn）此前报道，包括九寨沟、长白山等热门景区早在9月30日发布的公告中就通知，10月2日、3日门票已提前售罄。 10月1日晚间22时22分浙江神仙居景区发布通知，神仙居景区10月2日（周五）客流已达承载上限，景区将关闭10月2日线上、线下售票及免票通道，并采取限流措施。 10月2日一早，就有多地景区发布限流公告。 如河南宝泉景区10月2日早上八点就发布限流公告称：宝泉崖天下10月2日预约售票数量已达上限，国庆假期期间宝泉旅游区将严格…"
