    "content": "广东四通集团股份有限公司（*ST四通，603838.SH）9月30日公告披露，公司于近日收到中国证券监督管理委员会广东监管局出具的《关于对广东四通集团股份有限公司采取责令改正措施并对邓建华、蔡镇通、张平采取出具警示函措施的决定》（〔2026〕122号）（下称“警示函”）。 《警示函》显示，经查，*ST四通在收入核算及资产减值损失方面存在不准确，导致多期定期报告数据与实际情况存在差异、相关年报报告披露数据不准确。 具体而言，一是收入核算不准确。*ST四通2025年一季报、半年报、三季报错将有关交易计入营业收入，导致2…"
