    "pub_date": "2026-10-02 16:45:02",
    "author": "",
    "description": "02/10/2026 - 10:32 美国对台军售终于迎来了一些新进展。周五（10月2日），台湾接收了首批两架新一代F-16V战斗机，这批战机属于一项总额80亿美元的采购案，是2019年美国总统特朗普第一任期内获得华盛顿批准的，其中包含66架F-16V战斗机。 F-16V是一款第四代多用途战斗机，相较台湾现役老旧的F-16A/B机型有大幅升级。台湾此前已完成141架F-16A/B战机的性能提升计划，并于2023年底全部升级完毕。 台湾在…",
    "content": "02/10/2026 - 10:32 美国对台军售终于迎来了一些新进展。周五（10月2日），台湾接收了首批两架新一代F-16V战斗机，这批战机属于一项总额80亿美元的采购案，是2019年美国总统特朗普第一任期内获得华盛顿批准的，其中包含66架F-16V战斗机。 F-16V是一款第四代多用途战斗机，相较台湾现役老旧的F-16A/B机型有大幅升级。台湾此前已完成141架F-16A/B战机的性能提升计划，并于2023年底全部升级完毕。 台湾在防务装备方面仍高度依赖美国供应，同时也面临来自美国的压力，要求台湾投入更多资源用…"
