    "content": "新华社兰州10月2日电（记者何问）10月2日起，舞剧《永不消逝的电波》在甘肃省敦煌大剧院上演。国庆假期，前来敦煌的游客收到“大礼包”，白天观景，晚上观剧。 舞剧《永不消逝的电波》宣传海报图。新华社发 这个10月，敦煌正迎来一场密集的“演出季”。除《永不消逝的电波》外，舞剧《杜甫》、舞蹈诗剧《只此青绿》还将陆续登陆敦煌大剧院。与此同时，《乐动敦煌》《又见敦煌》等本地常态化剧目持续上演，鸣沙山月牙泉、敦煌夜市等景区和街区也推出乐舞、巡游、非遗展示等活动。 “我们今年新提出‘演出季’这个概念，希望慢慢把它做成一个新的文化…"
