    "content": "快科技10月2日消息，据报道， 新加坡男子叶林（音译）今年8月疑似出于玩笑，用谷歌Gemini生成了一张咸水鳄出现在Pandan水库的AI图片并发送给同事。 这张图随后被上报至新加坡国家水务局PUB，PUB和国家公园局随即暂停该区域所有水上活动两天，展开搜寻一条根本不存在的鳄鱼，直到次日确认图片为伪造后才报警，叶林被逮捕。 叶林面临的指控远比他预想的严重，新加坡法律规定传播虚假信息罪最高可判三年监禁、罚款1万新元或两者并罚。 而他在事发后删除了手机中的图片和Gemini应用试图掩盖，这一举动又被追加妨碍司法指控，最…"
