    "author": "李明睿",
    "description": "新华社北京10月2日电 据俄罗斯新闻社2日报道，国际原子能机构总干事拉斐尔·格罗西说，在俄乌冲突和平解决取得进展前，扎波罗热核电站的安全风险将持续存在。 9月14日，在奥地利维也纳，国际原子能机构总干事格罗西在国际原子能机构第70届大会上致辞。新华社记者贺灿铃摄 格罗西表示，国际原子能机构围绕此核电站的工作将持续展开，支持保障其安全的各项必要措施，这些工作“至少有助于维持一定程度的稳定”。 按俄新社说法，受持续冲突和输电线路受损等因素影…",
    "content": "新华社北京10月2日电 据俄罗斯新闻社2日报道，国际原子能机构总干事拉斐尔·格罗西说，在俄乌冲突和平解决取得进展前，扎波罗热核电站的安全风险将持续存在。 9月14日，在奥地利维也纳，国际原子能机构总干事格罗西在国际原子能机构第70届大会上致辞。新华社记者贺灿铃摄 格罗西表示，国际原子能机构围绕此核电站的工作将持续展开，支持保障其安全的各项必要措施，这些工作“至少有助于维持一定程度的稳定”。 按俄新社说法，受持续冲突和输电线路受损等因素影响，扎波罗热核电站的安全切实存在风险。该核电站多次失去冷却设备等核安全系统运行所…"
