    "content": "快科技10月2日消息，这两天微软开始升级Win11 26H2系统了，很多人已经收到了推送，它对CPU及内存的要求没有变，但会把不支持SSE4.2指令集的CPU排除在外，老旧CPU是不支持的。 好消息是这个限制又被破解了，已经有网友在AMD 的Phenom X4 9600处理器上启动了，而它是2007年发布， 是20年前的CPU了，并不支持SSE4.2指令集。 绕过这个限制的过程说起来也不算复杂，微软从Win11 24H2开始不仅要求支持TPM 2.0，还要CPU支持SSE4.2指令集，这是Intel 2008年推出…"
