    "content": "美国田纳西州的死囚克里斯塔·派克在被注射致命药物后，却仍有心跳，还被听到发出了打鼾声。 据中新网报道，派克的一位律师表示，现年50岁的派克被注射了两剂戊巴比妥后，正在医院“接受抢救”。 30年前，派克曾因谋杀被定罪，是田纳西州唯一被关押在死囚牢房的女性。如果此次执行成功，她将成为田纳西州200多年来首位被处决的女性。 而执行失败有多重原因。有医学专家认为，在处决尝试的过程中，戊巴比妥很可能没有进入派克的血液循环。此外，戊巴比妥的药效、派克的静脉脆弱都是潜在原因。但无论是什么原因，派克很可能会遭受脑损伤。 目前，田纳…"
