    "description": "新华社布宜诺斯艾利斯10月1日电（记者张铎）阿根廷国家科学与技术研究理事会1日说，初步确认在该国马德普拉塔海底发现57种新物种。 国家科学与技术研究理事会在一份声明中称，该机构科学家经过一年多努力，日前完成了对“4号陆坡”科考活动所收集样品的分析和归类，研究人员初步鉴定出57种可能为科学界此前未知的海洋物种，其中包括20种桡足类、22种棘皮动物、14种刺胞动物和1种掘足类软体动物。研究还发现5个新属，涉及珊瑚、海参和甲壳类动物。 据介绍…",
    "content": "新华社布宜诺斯艾利斯10月1日电（记者张铎）阿根廷国家科学与技术研究理事会1日说，初步确认在该国马德普拉塔海底发现57种新物种。 国家科学与技术研究理事会在一份声明中称，该机构科学家经过一年多努力，日前完成了对“4号陆坡”科考活动所收集样品的分析和归类，研究人员初步鉴定出57种可能为科学界此前未知的海洋物种，其中包括20种桡足类、22种棘皮动物、14种刺胞动物和1种掘足类软体动物。研究还发现5个新属，涉及珊瑚、海参和甲壳类动物。 据介绍，“4号陆坡”是继2012至2013年的“1号陆坡”“2号陆坡”和“3号陆坡”之…"
