    "content": "IT之家 10 月 2 日消息，据日媒 ITMedia 报道，东京都交通局 9 月 29 日宣布，将在 2028 年 11 月前全面撤除都营地铁（都営地下鉄）各车站内设置的公用电话。 东京都交通局表示，此举主要是为了应对公用电话使用人数减少以及通信环境变化。长期以来作为车站内重要通信手段的公用电话，将陆续退出历史舞台，交通局呼吁乘客对此予以理解。 此次撤除工作将分阶段进行。对于计划撤除的公用电话，工作人员将在实际撤除日期前至少两周张贴“公用电话撤除通知”，提前告知乘客。撤除后，用户如需查询附近公用电话的位置，可通过…"
