    "content": "Embassy of India in Israel / 印度政府赞扬斯米特·马查尔（Smit Machchhar）展现“非凡勇气”。 一架从阿联酋杜拜飞往以色列的客机上，在9月30日发生企图空中劫机事件。其中一名机师刺伤另一名机师后，乘客与机组人员合力制止施袭者，客机改降沙乌地阿拉伯，安全降落。 遭刺伤的机师证实为印度籍机长斯米特·马查尔（Capt Smit Machchhar），他被送往沙乌地阿拉伯西北部城市塔布克（Tabuk）的医院治疗。 印度驻阿拉伯联合大公国大使馆表示，马查尔“健康状况良好，恢复情况理想”…"
