    "content": "记者日前从内蒙古自治区林业和草原局获悉，根据最新公布的《内蒙古自治区“十五五”林业和草原保护利用规划》，今后5年内蒙古将完成生态建设任务1.57亿亩以上，进一步筑牢我国北方重要生态安全屏障。 内蒙古境内有巴丹吉林、腾格里、乌兰布和、库布其四大沙漠和毛乌素、浑善达克、科尔沁、呼伦贝尔四大沙地，生态治理任务艰巨。 工人在内蒙古乌兰布和沙漠综合治理示范区浇水。新华社记者李云平 摄 据介绍，今后5年，内蒙古以防沙治沙为主攻方向，全面打好“三北”工程攻坚战，规范发展光伏治沙，拓展实施改草治沙、以路治沙、科技治沙，强化联防联治…"
