    "content": "当财务提出“两张报表”需求时，直接画原型可能只是把Excel的麻烦搬进系统。本文通过一个真实案例，拆解产品经理如何通过追问发现核账、内部分析等隐藏场景，并做出可执行的取舍，为评估产品经理能力提供了可观察的证据。 一项财务报表需求，最初是这样被提出来的：做两张结算报表，补上需要的字段，两张都要能导出 Excel。 页面形式有了，功能也明确。如果只看这些，接下来似乎就是整理字段、画原型、评审和排期。等两个导出按钮做好，需求也就交付了。 但财务拿到文件之后，还要完成什么工作？为什么一定是两张表？这两件事如果没问清楚，页面…"
