    "author": "林威",
    "description": "新华社渥太华10月1日电（记者林威）加拿大政府1日将一条拟修建的西海岸石油管道改名为“太平洋联线管道”，并将其列为“国家利益”项目，预计该项目将大幅降低加石油通过管道运输的对美依赖。 据加拿大枢密院指令说明文件，结合跨山输油管道系统的优化，该项目带来的出口能力提升有望将加拿大对美国石油管道外输的依赖度从2025年约82%-83%降至65%-70%，还有望使加拿大重质原油与西得克萨斯轻质原油之间的每桶价差缩小3至5美元。 文件显示，加拿大…",
    "content": "新华社渥太华10月1日电（记者林威）加拿大政府1日将一条拟修建的西海岸石油管道改名为“太平洋联线管道”，并将其列为“国家利益”项目，预计该项目将大幅降低加石油通过管道运输的对美依赖。 据加拿大枢密院指令说明文件，结合跨山输油管道系统的优化，该项目带来的出口能力提升有望将加拿大对美国石油管道外输的依赖度从2025年约82%-83%降至65%-70%，还有望使加拿大重质原油与西得克萨斯轻质原油之间的每桶价差缩小3至5美元。 文件显示，加拿大对美国主导的石油出口基础设施具有结构性依赖。 文件还显示，“太平洋联线管道”全长…"
