    "content": "乌蒙苍莽，金沙奔涌。 90多年前，红军将士转战云南。从滇东北乌蒙山区到金沙江畔，一次次重大抉择、一次次艰险突围，在云岭大地留下深深的红色印记。 今天，记者沿着红军走过的路再次出发，一路看到革命旧址得到保护利用，红色故事代代讲述，昔日闭塞的山乡产业兴旺，曾横亘在红军面前的金沙江天险，已成为我国重要的清洁能源基地。 山河巨变，精神长存。 乌蒙回响 初心如磐 乌蒙山深处，云南省昭通市威信县扎西镇，青瓦木楼间，扎西会议旧址静静矗立。 1935年2月，中共中央先后在威信县境内的水田寨花房子、大河滩庄子上、扎西镇江西会馆召开政…"
