    "title": "防控松材线虫，林草部门再开展攻坚行动",
    "link": "http://www.news.cn/20261002/f9b9f24a856c4c1e98b2950d7f6d75f1/c.html",
    "pub_date": "2026-10-02 14:25:58",
    "author": "黄垚",
    "description": "松材线虫是我国危害最大的林业有害生物之一。记者近日从国家林草局获悉，为巩固拓展“十四五”攻坚成果，林草部门决定在“十五五”时期开展新一轮五年攻坚行动。 林草部门印发的“十五五”疫情防控攻坚行动方案，明确到2030年将疫情面积控制在1000万亩以下、县级疫区数量控制在600个以下的总体目标。 据介绍，“十四五”期间，国家林草局组织开展了松材线虫病疫情防控五年攻坚行动。全国县级疫区、乡级疫点、发生面积和病死树数量实现“四下降”，疫情快速扩散…",
    "content": "松材线虫是我国危害最大的林业有害生物之一。记者近日从国家林草局获悉，为巩固拓展“十四五”攻坚成果，林草部门决定在“十五五”时期开展新一轮五年攻坚行动。 林草部门印发的“十五五”疫情防控攻坚行动方案，明确到2030年将疫情面积控制在1000万亩以下、县级疫区数量控制在600个以下的总体目标。 据介绍，“十四五”期间，国家林草局组织开展了松材线虫病疫情防控五年攻坚行动。全国县级疫区、乡级疫点、发生面积和病死树数量实现“四下降”，疫情快速扩散态势得到有效遏制。2025年秋普结果显示，全国疫情发生面积较2020年减少124…"
