    "author": "田晓航",
    "description": "新华社北京10月2日电（记者田晓航）秋冬时节正是利用膏方进补调养的黄金窗口期。中国中医科学院西苑医院第十七届膏方养生文化节日前拉开帷幕，文化节期间，中医专家为公众详解膏方服用注意事项。 “不同功效的膏方，服用时间不尽相同。”中国中医科学院西苑医院药学部副主任药师庞颖举例说，滋补类宜空腹服用，补心脾、安心神、镇静安眠类宜睡前15至30分钟服用。 膏方适合冲服或者含服，服用剂量应根据膏方性质、体质强弱及疾病轻重等情况综合考虑决定。 庞颖介绍…",
    "content": "新华社北京10月2日电（记者田晓航）秋冬时节正是利用膏方进补调养的黄金窗口期。中国中医科学院西苑医院第十七届膏方养生文化节日前拉开帷幕，文化节期间，中医专家为公众详解膏方服用注意事项。 “不同功效的膏方，服用时间不尽相同。”中国中医科学院西苑医院药学部副主任药师庞颖举例说，滋补类宜空腹服用，补心脾、安心神、镇静安眠类宜睡前15至30分钟服用。 膏方适合冲服或者含服，服用剂量应根据膏方性质、体质强弱及疾病轻重等情况综合考虑决定。 庞颖介绍，膏方一般每日服用两次，成人每次取常用汤匙1匙的量（约20克），儿童10克至15…"
