    "content": "新华社日内瓦10月1日电（记者王娅楠）瑞士科学院1日援引瑞士冰川监测网最新数据发布的公报说，过去5年间，瑞士冰川的总冰量减少了近五分之一。 公报说，2026年瑞士冰川冰量减少5.5%，损失量在有记录以来排名第二，仅次于2022年。单座冰川的平均厚度减少了2.5至4米，今年夏季部分冰川舌区域的冰层厚度甚至减少了10米。 一个完整的冰川年一般从秋季开始，到次年夏末结束。公报说，2026年5月至9月的强烈热浪，叠加冬季降雪稀少，使今年再次成为瑞士冰川遭受严重损失的一年。从平均积雪深度来看，2025年11月至2026年4月…"
